const cfg = $('Edit Your Watchlist').first().json;
const tickers = String(cfg.tickers || '')
  .split(',').map(t => t.trim().toUpperCase()).filter(Boolean);
if (!tickers.length) {
  throw new Error("The watchlist is empty — add tickers in 'Edit Your Watchlist'.");
}
return tickers.map(ticker => ({ json: { ticker } }));

// Market Brief Pro — deterministic indicator engine.
// This exact function body is embedded in the "Compute the Technical
// Indicators" Code node of 13-market-brief-pro.json. Keep the two in sync:
// edit here, run `node market-brief-indicators.test.js`, then re-generate.
//
// Input: Twelve Data /time_series JSON (values newest-first).
// Output: one flat object of indicators + detected events.

function computeIndicators(td) {
  if (!td || !td.values || !Array.isArray(td.values) || td.values.length < 60) {
    throw new Error(
      `Not enough price history for ${td && td.meta ? td.meta.symbol : 'ticker'} — need at least 60 daily bars, got ${td && td.values ? td.values.length : 0}. Check the symbol spelling.`
    );
  }
  // Twelve Data returns newest-first; all math below needs oldest-first.
  const bars = [...td.values].reverse().filter(v => v && v.close != null);
  const closes = bars.map(v => Number(v.close));
  const n = closes.length;
  const last = closes[n - 1];
  const prev = closes[n - 2];

  const sma = (p) => {
    if (n < p) return null;
    let s = 0;
    for (let i = n - p; i < n; i++) s += closes[i];
    return s / p;
  };

  // EMA over the full series (converges long before the end).
  const emaSeries = (p) => {
    const k = 2 / (p + 1);
    const out = [closes[0]];
    for (let i = 1; i < n; i++) out.push(closes[i] * k + out[i - 1] * (1 - k));
    return out;
  };

  // RSI-14 with Wilder smoothing — plain averages diverge from
  // TradingView and buyers notice.
  const rsiSeries = (p = 14) => {
    let gain = 0, loss = 0;
    for (let i = 1; i <= p; i++) {
      const d = closes[i] - closes[i - 1];
      if (d > 0) gain += d; else loss -= d;
    }
    let avgGain = gain / p, avgLoss = loss / p;
    const out = new Array(p).fill(null);
    out.push(avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss));
    for (let i = p + 1; i < n; i++) {
      const d = closes[i] - closes[i - 1];
      avgGain = (avgGain * (p - 1) + Math.max(d, 0)) / p;
      avgLoss = (avgLoss * (p - 1) + Math.max(-d, 0)) / p;
      out.push(avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss));
    }
    return out;
  };

  const ema12 = emaSeries(12), ema26 = emaSeries(26);
  const macdLine = ema12.map((v, i) => v - ema26[i]);
  // Signal line: EMA-9 of the MACD line.
  const k9 = 2 / 10;
  const signal = [macdLine[0]];
  for (let i = 1; i < n; i++) signal.push(macdLine[i] * k9 + signal[i - 1] * (1 - k9));
  const hist = macdLine[n - 1] - signal[n - 1];
  const histPrev = macdLine[n - 2] - signal[n - 2];

  const sma20 = sma(20), sma50 = sma(50), sma200 = sma(200);
  // Yesterday's SMAs for cross detection.
  const smaAt = (p, end) => {
    if (end < p) return null;
    let s = 0;
    for (let i = end - p; i < end; i++) s += closes[i];
    return s / p;
  };
  const sma50y = smaAt(50, n - 1), sma200y = smaAt(200, n - 1);

  // Bollinger 20,2
  let bbUpper = null, bbLower = null, bbPos = null;
  if (sma20 != null) {
    let v = 0;
    for (let i = n - 20; i < n; i++) v += (closes[i] - sma20) ** 2;
    const sd = Math.sqrt(v / 20);
    bbUpper = sma20 + 2 * sd;
    bbLower = sma20 - 2 * sd;
    bbPos = bbUpper === bbLower ? 0.5 : (last - bbLower) / (bbUpper - bbLower);
  }

  const rsiAll = rsiSeries(14);
  const rsi = rsiAll[n - 1], rsiPrev = rsiAll[n - 2];

  const win52 = closes.slice(-252);
  const hi52 = Math.max(...win52), lo52 = Math.min(...win52);
  const range52Pos = hi52 === lo52 ? 0.5 : (last - lo52) / (hi52 - lo52);

  // Simple 20-day annualized volatility from daily log returns.
  const rets = [];
  for (let i = Math.max(1, n - 20); i < n; i++) rets.push(Math.log(closes[i] / closes[i - 1]));
  const mean = rets.reduce((a, b) => a + b, 0) / rets.length;
  const vol20 =
    Math.sqrt(rets.reduce((a, b) => a + (b - mean) ** 2, 0) / rets.length) * Math.sqrt(252);

  const events = [];
  if (sma50 != null && sma200 != null && sma50y != null && sma200y != null) {
    if (sma50y <= sma200y && sma50 > sma200) events.push('GOLDEN_CROSS');
    if (sma50y >= sma200y && sma50 < sma200) events.push('DEATH_CROSS');
  }
  if (rsi != null) {
    if (rsi >= 70) events.push('RSI_OVERBOUGHT');
    if (rsi <= 30) events.push('RSI_OVERSOLD');
    if (rsiPrev != null && rsiPrev < 30 && rsi >= 30) events.push('RSI_RECOVERY');
  }
  if (histPrev <= 0 && hist > 0) events.push('MACD_BULLISH_CROSS');
  if (histPrev >= 0 && hist < 0) events.push('MACD_BEARISH_CROSS');
  if (bbPos != null) {
    if (bbPos > 1) events.push('ABOVE_UPPER_BOLLINGER');
    if (bbPos < 0) events.push('BELOW_LOWER_BOLLINGER');
  }

  // ATR-14 (Wilder) from true ranges — high/low come with the same bars.
  // Powers the suggested stop level (close - 2*ATR), the risk number
  // traders actually act on. Degrades to null if the feed omits high/low.
  let atr = null, atrPct = null, stopSuggest = null;
  const highs = bars.map(v => (v.high != null ? Number(v.high) : null));
  const lows = bars.map(v => (v.low != null ? Number(v.low) : null));
  if (n > 15 && highs.every(h => h != null) && lows.every(l => l != null)) {
    const trs = [];
    for (let i = 1; i < n; i++) {
      trs.push(Math.max(
        highs[i] - lows[i],
        Math.abs(highs[i] - closes[i - 1]),
        Math.abs(lows[i] - closes[i - 1])
      ));
    }
    let a = 0;
    for (let i = 0; i < 14; i++) a += trs[i];
    a /= 14;
    for (let i = 14; i < trs.length; i++) a = (a * 13 + trs[i]) / 14;
    atr = a;
    atrPct = (a / last) * 100;
    stopSuggest = last - 2 * a;
  }

  // Consecutive up/down closes ending today (0 = flat yesterday).
  let streak = 0;
  for (let i = n - 1; i > 0; i--) {
    const d = closes[i] - closes[i - 1];
    if (d === 0) break;
    if (streak === 0) streak = d > 0 ? 1 : -1;
    else if (d > 0 === streak > 0) streak += streak > 0 ? 1 : -1;
    else break;
  }

  // Fresh 52-week extremes: today's close vs the whole prior window.
  const prior = closes.slice(Math.max(0, n - 252), n - 1);
  if (prior.length >= 59) {
    if (last > Math.max(...prior)) events.push('NEW_52W_HIGH');
    if (last < Math.min(...prior)) events.push('NEW_52W_LOW');
  }
  if (streak >= 5) events.push('UP_STREAK_' + streak);
  if (streak <= -5) events.push('DOWN_STREAK_' + -streak);

  const round = (x, d = 2) => (x == null ? null : Number(x.toFixed(d)));

  return {
    symbol: td.meta.symbol,
    exchange: td.meta.exchange || '',
    close: round(last),
    changePct: round(((last - prev) / prev) * 100),
    sma20: round(sma20), sma50: round(sma50), sma200: round(sma200),
    aboveSma200: sma200 != null ? last > sma200 : null,
    rsi14: round(rsi, 1),
    macd: round(macdLine[n - 1], 3),
    macdSignal: round(signal[n - 1], 3),
    macdHist: round(hist, 3),
    bbUpper: round(bbUpper), bbLower: round(bbLower),
    bbPos: round(bbPos, 2),
    hi52: round(hi52), lo52: round(lo52),
    range52Pos: round(range52Pos, 2),
    vol20Ann: round(vol20, 3),
    atr14: round(atr), atrPct: round(atrPct, 1),
    stopSuggest: round(stopSuggest),
    streak,
    events,
    spark: closes.slice(-30).map(c => round(c)),
    bars: n,
  };
}

const td = $input.first().json;
const ticker = $('Loop Over Each Ticker').first().json.ticker;
try {
  if (td.error) throw new Error(String(td.error.message || td.error));
  if (td.status === 'error') {
    throw new Error(`Twelve Data: ${td.message || 'unknown error'} (check the symbol and your API key)`);
  }
  return [{ json: computeIndicators(td) }];
} catch (e) {
  // One bad symbol or API hiccup must not kill the whole morning brief —
  // ship a data-error card; the report renders it and the rest goes out.
  return [{ json: { symbol: ticker, dataError: String(e.message || e), events: [], spark: [], headlines: [] } }];
}

const ind = $('Compute the Technical Indicators').first().json;
const headlines = $input.all()
  .filter(a => a.json && a.json.title)
  .slice(0, 5)
  .map(a => ({ title: a.json.title, link: a.json.link || '' }));
return [{ json: { ...ind, headlines } }];

