const t = $('Keep the Top Headlines').first().json;
if (t.dataError) {
  return [{ json: { ...t, score: null, verdict: 'NO DATA',
    topReasons: ['price data unavailable'],
    sentiment: { sentiment: 0, catalyst: '', summary: '' } } }];
}

// Parse the AI's sentiment JSON defensively.
let sent = { sentiment: 0, catalyst: 'no news', summary: '' };
try {
  let s = String($input.first().json.text ?? '').trim()
    .replace(/^```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a !== -1 && b !== -1) {
    const p = JSON.parse(s.slice(a, b + 1));
    if (typeof p.sentiment === 'number') {
      sent = {
        sentiment: Math.max(-1, Math.min(1, p.sentiment)),
        catalyst: String(p.catalyst || ''),
        summary: String(p.summary || ''),
      };
    }
  }
} catch (e) { /* neutral fallback keeps the report alive */ }

// ---- Composite score: weights are the strategy — edit them here. ----
// trend 35 + momentum 30 + sentiment 25 + volatility 10 = 100
const reasons = [];
let trend = 0;
if (t.aboveSma200) { trend += 15; reasons.push(['above its 200-day average', 15]); }
if (t.sma50 != null && t.close > t.sma50) { trend += 10; reasons.push(['price above the 50-day', 10]); }
if (t.sma50 != null && t.sma200 != null && t.sma50 > t.sma200) { trend += 10; reasons.push(['50-day above 200-day (uptrend)', 10]); }

let momentum = 0;
if (t.rsi14 != null) {
  if (t.rsi14 >= 45 && t.rsi14 <= 70) { momentum += 12; reasons.push(['healthy RSI', 12]); }
  else if (t.rsi14 > 70) { momentum += 6; reasons.push(['RSI overbought', -6]); }
  else if (t.rsi14 >= 30) { momentum += 8; }
  else { momentum += 3; reasons.push(['RSI oversold', -9]); }
}
if (t.macdHist != null && t.macdHist > 0) { momentum += 10; reasons.push(['MACD momentum positive', 10]); }
else { reasons.push(['MACD momentum negative', -10]); }
if (t.events.includes('RSI_RECOVERY')) { momentum += 5; reasons.push(['RSI recovering from oversold', 5]); }
if (t.events.includes('MACD_BULLISH_CROSS')) { momentum += 3; reasons.push(['fresh MACD bullish cross', 3]); }
momentum = Math.min(momentum, 30);

const sentimentPts = Math.round(((sent.sentiment + 1) / 2) * 25);
if (sent.sentiment > 0.25) reasons.push(['positive news: ' + (sent.catalyst || 'flow'), sentimentPts]);
if (sent.sentiment < -0.25) reasons.push(['negative news: ' + (sent.catalyst || 'flow'), sentimentPts - 13]);

let volatility = 2;
if (t.vol20Ann != null) {
  volatility = t.vol20Ann < 0.2 ? 10 : t.vol20Ann < 0.35 ? 7 : t.vol20Ann < 0.5 ? 4 : 2;
  if (t.vol20Ann >= 0.5) reasons.push(['very high volatility', -8]);
}

const score = Math.max(0, Math.min(100, trend + momentum + sentimentPts + volatility));
const verdict = score >= 65 ? 'BUY' : score >= 45 ? 'HOLD' : 'AVOID';
const topReasons = reasons
  .sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]))
  .slice(0, 2).map(r => r[0]);

return [{ json: { ...t, sentiment: sent, score, verdict, topReasons } }];

const cards = $input.all().map(i => i.json);

// Latest previous score per symbol from the Sheets history (may be empty).
let history = [];
try { history = $('Read the Score History From Google Sheets').all().map(i => i.json); }
catch (e) { history = []; }
const prevBySymbol = {};
for (const row of history) {
  const sym = String(row.Symbol || '').toUpperCase();
  if (!sym || row.Score == null || row.Score === '') continue;
  const cur = prevBySymbol[sym];
  if (!cur || String(row.Date) > String(cur.Date)) prevBySymbol[sym] = row;
}

const alerts = [];
for (const c of cards) {
  const prev = prevBySymbol[c.symbol];
  c.prevScore = prev ? Number(prev.Score) : null;
  c.scoreDelta = c.prevScore != null ? Math.round(c.score - c.prevScore) : null;
  if (prev && prev.Verdict && prev.Verdict !== c.verdict) {
    alerts.push(`${c.symbol}: verdict flipped ${prev.Verdict} → ${c.verdict}`);
  }
  for (const ev of c.events) {
    alerts.push(`${c.symbol}: ${ev.replace(/_/g, ' ').toLowerCase()}`);
  }
  if (c.dataError) alerts.push(`${c.symbol}: ⚠ ${c.dataError}`);
}

cards.sort((a, b) => (b.score ?? -1) - (a.score ?? -1));
const today = new Date().toISOString().slice(0, 10);
return [{ json: { date: today, tickers: cards, alerts } }];

const b = $input.first().json;
return b.tickers.filter(t => t.score != null).map(t => ({
  json: { Date: b.date, Symbol: t.symbol, Score: t.score, Verdict: t.verdict },
}));

const brief = $('Rank the Watchlist and Detect Flips').first().json;
let crypto = [];
try {
  crypto = $input.all()
    .filter(i => i.json && i.json.symbol && i.json.current_price != null)
    .map(i => ({
      name: i.json.name,
      symbol: String(i.json.symbol).toUpperCase(),
      price: i.json.current_price,
      change24h: i.json.price_change_percentage_24h_in_currency ?? i.json.price_change_percentage_24h ?? null,
      change7d: i.json.price_change_percentage_7d_in_currency ?? null,
    }));
} catch (e) { crypto = []; }
return [{ json: { ...brief, crypto } }];

const b = $('Merge Crypto Into the Brief').first().json;
const summary = String($input.first().json.text || '').trim();

const fmt = (x, d = 2) => (x == null ? '—' : Number(x).toLocaleString('en-US', { maximumFractionDigits: d }));
const pct = (x) => (x == null ? '—' : (x > 0 ? '+' : '') + Number(x).toFixed(2) + '%');
const vColor = (v) => (v === 'BUY' ? '#1a7f37' : v === 'HOLD' ? '#9a6700' : v === 'NO DATA' ? '#57606a' : '#cf222e');

function spark(points) {
  if (!points || points.length < 2) return '';
  const w = 120, h = 30;
  const min = Math.min(...points), max = Math.max(...points);
  const xs = points.map((p, i) => {
    const x = (i / (points.length - 1)) * w;
    const y = max === min ? h / 2 : h - ((p - min) / (max - min)) * (h - 4) - 2;
    return x.toFixed(1) + ',' + y.toFixed(1);
  });
  const up = points[points.length - 1] >= points[0];
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg"><polyline fill="none" stroke="${up ? '#1a7f37' : '#cf222e'}" stroke-width="1.5" points="${xs.join(' ')}"/></svg>`;
}

const rows = b.tickers.map((t, i) => `
  <tr style="border-bottom:1px solid #d8dee4">
    <td style="padding:8px 10px;font-weight:600">${i + 1}. ${t.symbol}</td>
    <td style="padding:8px 10px;text-align:right">${fmt(t.close)}</td>
    <td style="padding:8px 10px;text-align:right;color:${(t.changePct ?? 0) >= 0 ? '#1a7f37' : '#cf222e'}">${pct(t.changePct)}</td>
    <td style="padding:8px 10px;text-align:center;font-weight:700;color:${vColor(t.verdict)}">${t.verdict}</td>
    <td style="padding:8px 10px;text-align:right">${t.score ?? '—'}${t.scoreDelta != null ? ` <span style="color:${t.scoreDelta >= 0 ? '#1a7f37' : '#cf222e'};font-size:12px">(${t.scoreDelta >= 0 ? '+' : ''}${t.scoreDelta})</span>` : ''}</td>
    <td style="padding:4px 10px">${spark(t.spark)}</td>
  </tr>`).join('');

const cards = b.tickers.map(t => t.dataError ? `
  <div style="border:1px solid #d4a72c;border-radius:8px;padding:14px;margin:10px 0;background:#fff8c5">
    <div style="font-size:15px;font-weight:700">${t.symbol} <span style="float:right;color:#57606a">NO DATA</span></div>
    <div style="font-size:13px;color:#57606a;margin-top:6px">⚠ ${t.dataError}</div>
  </div>` : `
  <div style="border:1px solid #d8dee4;border-radius:8px;padding:14px;margin:10px 0">
    <div style="font-size:15px;font-weight:700">${t.symbol} — ${fmt(t.close)} <span style="color:${(t.changePct ?? 0) >= 0 ? '#1a7f37' : '#cf222e'}">${pct(t.changePct)}</span>${t.streak != null && Math.abs(t.streak) >= 3 ? ` <span style="font-size:11px;background:${t.streak > 0 ? '#dafbe1' : '#ffebe9'};border-radius:10px;padding:2px 8px">${Math.abs(t.streak)}d ${t.streak > 0 ? 'up' : 'down'} streak</span>` : ''}
      <span style="float:right;color:${vColor(t.verdict)}">${t.verdict} · ${t.score}/100</span></div>
    <div style="font-size:13px;color:#57606a;margin:6px 0">${(t.topReasons || []).join(' · ') || '—'}</div>
    <table style="font-size:12.5px;color:#24292f;border-collapse:collapse"><tr>
      <td style="padding:2px 14px 2px 0">RSI-14 <b>${fmt(t.rsi14, 1)}</b></td>
      <td style="padding:2px 14px 2px 0">MACD hist <b>${fmt(t.macdHist, 3)}</b></td>
      <td style="padding:2px 14px 2px 0">SMA50 <b>${fmt(t.sma50)}</b></td>
      <td style="padding:2px 14px 2px 0">SMA200 <b>${fmt(t.sma200)}</b></td>
      <td style="padding:2px 14px 2px 0">52-w pos <b>${t.range52Pos != null ? Math.round(t.range52Pos * 100) + '%' : '—'}</b></td>
    </tr><tr>
      <td style="padding:2px 14px 2px 0">ATR-14 <b>${fmt(t.atr14)}</b>${t.atrPct != null ? ` <span style="color:#57606a">(${fmt(t.atrPct, 1)}%)</span>` : ''}</td>
      <td style="padding:2px 14px 2px 0" colspan="2">suggested stop ≈ <b>${fmt(t.stopSuggest)}</b> <span style="color:#57606a">(close − 2×ATR)</span></td>
      <td style="padding:2px 14px 2px 0" colspan="2">Bollinger pos <b>${t.bbPos != null ? Math.round(t.bbPos * 100) + '%' : '—'}</b></td>
    </tr></table>
    ${t.sentiment && t.sentiment.summary ? `<div style="font-size:12.5px;color:#57606a;margin-top:6px">📰 ${t.sentiment.summary}</div>` : ''}
    ${(t.headlines || []).slice(0, 3).map(h => `<div style="font-size:12px;margin-top:3px"><a href="${h.link}" style="color:#0969da;text-decoration:none">› ${h.title}</a></div>`).join('')}
  </div>`).join('');

const cryptoRows = (b.crypto || []).map(c => `
  <tr style="border-bottom:1px solid #d8dee4">
    <td style="padding:6px 10px">${c.name} (${c.symbol})</td>
    <td style="padding:6px 10px;text-align:right">$${fmt(c.price)}</td>
    <td style="padding:6px 10px;text-align:right;color:${(c.change24h ?? 0) >= 0 ? '#1a7f37' : '#cf222e'}">${pct(c.change24h)}</td>
    <td style="padding:6px 10px;text-align:right;color:${(c.change7d ?? 0) >= 0 ? '#1a7f37' : '#cf222e'}">${pct(c.change7d)}</td>
  </tr>`).join('');

const alertsHtml = b.alerts.length
  ? `<div style="background:#fff8c5;border:1px solid #d4a72c;border-radius:8px;padding:10px 14px;margin:12px 0"><b>⚡ Signal flips</b><br>${b.alerts.map(a => '• ' + a).join('<br>')}</div>`
  : '';

const html = `<!doctype html><html><body style="margin:0;padding:0;background:#f6f8fa">
<div style="max-width:680px;margin:0 auto;padding:20px;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#24292f">
  <div style="background:#fff;border:1px solid #d8dee4;border-radius:10px;padding:20px">
    <h1 style="font-size:19px;margin:0 0 2px">📊 Market Brief — ${b.date}</h1>
    <div style="font-size:13px;color:#57606a;margin-bottom:12px">${b.tickers.length} tickers · ${(b.crypto || []).length} cryptos · computed indicators + AI news sentiment</div>
    <div style="font-size:14px;line-height:1.55;border-left:3px solid #0969da;padding-left:12px;margin:12px 0">${summary.replace(/\n/g, '<br>')}</div>
    ${alertsHtml}
    <table style="width:100%;border-collapse:collapse;font-size:13.5px;margin:8px 0">
      <tr style="text-align:left;color:#57606a;font-size:12px;text-transform:uppercase">
        <th style="padding:6px 10px">Ticker</th><th style="padding:6px 10px;text-align:right">Close</th>
        <th style="padding:6px 10px;text-align:right">Day</th><th style="padding:6px 10px;text-align:center">Verdict</th>
        <th style="padding:6px 10px;text-align:right">Score</th><th style="padding:6px 10px">30d</th>
      </tr>${rows}
    </table>
    ${cards}
    ${cryptoRows ? `<h2 style="font-size:15px;margin:16px 0 4px">Crypto</h2><table style="width:100%;border-collapse:collapse;font-size:13.5px">${cryptoRows}</table>` : ''}
    <div style="font-size:11.5px;color:#8b949e;margin-top:16px">Educational information only — not investment advice. Built with n8n · data: Twelve Data, Google News, CoinGecko.</div>
  </div>
</div></body></html>`;

const flip = b.alerts.length ? `⚡ ${b.alerts.slice(0, 6).join('\n⚡ ')}\n\n` : '';
const tgLines = b.tickers.map((t, i) =>
  `${i + 1}. ${t.symbol} ${t.verdict} ${t.score ?? '—'}${t.scoreDelta != null ? ` (${t.scoreDelta >= 0 ? '+' : ''}${t.scoreDelta})` : ''} · ${fmt(t.close)} ${pct(t.changePct)}`);
const tg = `📊 Market Brief — ${b.date}\n\n${flip}${tgLines.join('\n')}` +
  ((b.crypto || []).length ? '\n\n' + b.crypto.map(c => `${c.symbol} $${fmt(c.price)} ${pct(c.change24h)}`).join(' · ') : '') +
  '\n\nFull report in your inbox.';

return [{ json: { html, tg, subject: `📊 Market Brief ${b.date}: ` + b.tickers.filter(t => t.score != null).slice(0, 3).map(t => `${t.symbol} ${t.verdict}`).join(', ') } }];
